import { Radio as BaseRadio } from '@base-ui/react/radio';
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group';
import { createContext, useContext, useId, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { radioGroupVariants, type RadioGroupVariantProps } from './radio-group.variants';

type Variant = NonNullable<RadioGroupVariantProps['variant']>;
const VariantContext = createContext<Variant>('plain');

export interface RadioGroupProps<Value = string>
  extends Omit<BaseRadioGroup.Props<Value>, 'className'>,
    RadioGroupVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

/**
 * Single-choice group (role radiogroup). Arrow keys move and select; Tab enters the group
 * once, on the selected radio. Name it with `aria-labelledby`, or render it as a Fieldset:
 * `<Fieldset render={<RadioGroup />}>`. Variants: plain, list (bordered rows) and card.
 */
export function RadioGroup<Value = string>({ variant = 'plain', className, ...props }: RadioGroupProps<Value>) {
  return (
    <VariantContext.Provider value={variant}>
      <BaseRadioGroup<Value> className={cn(radioGroupVariants({ variant }).group(), className)} {...props} />
    </VariantContext.Provider>
  );
}

export interface RadioProps<Value = string> extends Omit<BaseRadio.Root.Props<Value>, 'className'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  /** Visible label. Without it, pass `aria-label`. */
  label?: ReactNode;
  /** Helper line under the label, linked with aria-describedby. */
  description?: ReactNode;
  /** Right-aligned content on the label row (e.g. a price in the card variant); announced as description. */
  trailing?: ReactNode;
}

/** One option of a RadioGroup. Identified by `value`. */
export function Radio<Value = string>({ label, description, trailing, className, ...props }: RadioProps<Value>) {
  const variant = useContext(VariantContext);
  const s = radioGroupVariants({ variant });
  const descId = useId();
  const trailingId = useId();
  const describedBy = [trailing != null && trailingId, description != null && descId].filter(Boolean).join(' ') || undefined;
  const control = (
    <BaseRadio.Root<Value>
      className={cn(s.radio(), label != null && 'mt-px', label == null && className)}
      aria-describedby={describedBy}
      {...props}
    >
      <BaseRadio.Indicator className={s.indicator()} />
    </BaseRadio.Root>
  );
  if (label == null) return control;
  return (
    <div className={cn(s.item(), className)}>
      <label className={s.label()}>
        {control}
        <span className={s.labelText()}>{label}</span>
      </label>
      {trailing != null && (
        <span id={trailingId} className={s.trailing()}>
          {trailing}
        </span>
      )}
      {description != null && (
        <p id={descId} className={s.description()}>
          {description}
        </p>
      )}
    </div>
  );
}

export { RadioGroup, Radio, type RadioGroupProps, type RadioProps } from './RadioGroup';
export { radioGroupVariants, type RadioGroupVariantProps } from './radio-group.variants';
export { doc as radioGroupDoc } from './RadioGroup.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const radioGroupVariants = tv({
  slots: {
    group: 'flex flex-col',
    radio: [
      'inline-flex size-[18px] shrink-0 cursor-pointer items-center justify-center rounded-full border border-border bg-background',
      'transition-colors motion-reduce:transition-none hover:border-muted-foreground/50',
      'data-checked:border-primary data-checked:bg-primary data-invalid:border-destructive/70',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      'data-disabled:cursor-not-allowed data-disabled:opacity-50',
    ],
    indicator: 'size-1.5 rounded-full bg-primary-foreground data-unchecked:hidden',
    item: 'grid grid-cols-[auto_1fr_auto] items-start gap-x-3 gap-y-0.5',
    label: 'col-span-2 grid cursor-pointer grid-cols-subgrid items-start has-[[data-disabled]]:cursor-not-allowed has-[[data-disabled]]:opacity-70',
    labelText: 'min-w-0 text-[13px] leading-5 font-medium text-foreground select-none',
    trailing: 'col-start-3 row-start-1 text-end text-[13px] leading-5 font-semibold text-foreground',
    description: 'col-start-2 col-end-4 text-[12.5px] leading-5 text-muted-foreground text-pretty',
  },
  variants: {
    variant: {
      plain: { group: 'gap-2.5' },
      list: {
        group: 'gap-0 divide-y divide-border/60 overflow-hidden rounded-md border border-border bg-background/40',
        item: 'px-4 py-3.5',
      },
      card: {
        group: 'gap-3',
        item: [
          'rounded-md border border-border bg-background px-4 py-3.5 transition-colors motion-reduce:transition-none',
          'hover:border-muted-foreground/40 has-[[data-checked]]:border-primary/60 has-[[data-checked]]:ring-2 has-[[data-checked]]:ring-primary/20',
          'has-[[data-disabled]]:hover:border-border',
        ],
        labelText: 'font-semibold',
        description: 'text-[12px]',
      },
    },
  },
  defaultVariants: { variant: 'plain' },
});

export type RadioGroupVariantProps = VariantProps<typeof radioGroupVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'RadioGroup',
  group: 'Forms',
  status: 'stable',
  description: 'Single choice from a short list. RadioGroup + Radio with optional label, description and trailing content per option, in plain, list (bordered rows) and card variants.',
  primitive: '@base-ui/react/radio-group, @base-ui/react/radio',
  pattern: 'radio group',
  keyboard: [
    ['Tab', 'Enters the group once, on the selected radio (or the first one); Tab again leaves the group'],
    ['Arrow Down / Arrow Right', 'Moves to the next radio and selects it (wraps)'],
    ['Arrow Up / Arrow Left', 'Moves to the previous radio and selects it (wraps)'],
    ['Space', 'Selects the focused radio if it is not already selected'],
  ],
  tokens: ['background', 'border', 'primary', 'primary-foreground', 'foreground', 'muted-foreground', 'destructive', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
